#'   \item{engine-location}{Location of the engine (e.g., front, rear)}
#'   \item{wheel-base}{Wheelbase of the vehicle in inches}
#'   \item{length}{Length of the vehicle in inches}
#'   \item{width}{Width of the vehicle in inches}
