#' Carbon Dioxide Uptake in Grass Plants
#'
#' The CO2 data frame has 84 rows and 5 columns of data from an experiment on the cold tolerance of the grass species Echinochloa crus-galli.
#'
#' @format A data frame with 84 rows and 5 variables:
#' \describe{
#'   \item{Plant}{an ordered factor with levels Qn1 < Qn2 < Qn3 < ... < Mc1 giving a unique identifier for each plant). Used as a grouping factor.}
#'   \item{Type}{a factor with levels Quebec Mississippi giving the origin of the plant}
#'   \item{Treatment}{a factor with levels nonchilled chilled}
#'   \item{conc}{a numeric vector of ambient carbon dioxide concentrations (mL/L)}
#'   \item{uptake}{a numeric vector of carbon dioxide uptake rates (in \eqn{\mu}mol/m²/sec)}
#' }
#'
#' @details
#' Grouped formulas like \code{uptake ~ conc | Plant} are useful in lattice graphics
#' and mixed-effect models. The vertical bar (`|`) separates the grouping variable.
#' This allows modeling or plotting the response (\code{uptake}) versus the predictor
#' (\code{conc}) within each level of \code{Plant}.
#' 
#' @source
#' Potvin, C., Lechowicz, M. J. and Tardif, S. (1990) “The statistical analysis of ecophysiological response curves obtained from experiments involving repeated measures”, Ecology, 71, 1389–1400.
#' Pinheiro, J. C. and Bates, D. M. (2000) Mixed-effects Models in S and S-PLUS, Springer.
#' @examples
#' data(df_co2)
#' head(df_co2)

"df_co2"

#' Big Five Personality Test Dataset
#'
#' This dataset contains responses to an interactive online Big Five personality test
#' conducted around 2012. Participants rated themselves on 50 personality statements,
#' and also provided demographic and technical metadata. Responses were collected
#' with informed consent, and missing data is coded as 0.
#'
#' @format A data frame with 19719 rows and 57 variables:
#' \describe{
#'   \item{race}{Race/ethnic background (1–13, 0=missing)}
#'   \item{age}{Age (integer; only responses from participants 13 and older included)}
#'   \item{engnat}{Is English your native language? (1=Yes, 2=No, 0=missing)}
#'   \item{gender}{1=Male, 2=Female, 3=Other, 0=missing}
#'   \item{hand}{Dominant writing hand: 1=Right, 2=Left, 3=Both, 0=missing}
#'   \item{source}{How participant came to the test site: 
#'     1=Internal link,
#'     2=Google,
#'     3=Facebook,
#'     4=.edu site,
#'     6=Other/unknown}
#'   \item{country}{Two-letter ISO country code (e.g., "US", "GB")}
#'   \item{E1}{I am the life of the party.}
#'   \item{E2}{I don't talk a lot.}
#'   \item{E3}{I feel comfortable around people.}
#'   \item{E4}{I keep in the background.}
#'   \item{E5}{I start conversations.}
#'   \item{E6}{I have little to say.}
#'   \item{E7}{I talk to a lot of different people at parties.}
#'   \item{E8}{I don't like to draw attention to myself.}
#'   \item{E9}{I don't mind being the center of attention.}
#'   \item{E10}{I am quiet around strangers.}
#'   \item{N1}{I get stressed out easily.}
#'   \item{N2}{I am relaxed most of the time.}
#'   \item{N3}{I worry about things.}
#'   \item{N4}{I seldom feel blue.}
#'   \item{N5}{I am easily disturbed.}
#'   \item{N6}{I get upset easily.}
#'   \item{N7}{I change my mood a lot.}
#'   \item{N8}{I have frequent mood swings.}
#'   \item{N9}{I get irritated easily.}
#'   \item{N10}{I often feel blue.}
#'   \item{A1}{I feel little concern for others.}
#'   \item{A2}{I am interested in people.}
#'   \item{A3}{I insult people.}
#'   \item{A4}{I sympathize with others' feelings.}
#'   \item{A5}{I am not interested in other people's problems.}
#'   \item{A6}{I have a soft heart.}
#'   \item{A7}{I am not really interested in others.}
#'   \item{A8}{I take time out for others.}
#'   \item{A9}{I feel others' emotions.}
#'   \item{A10}{I make people feel at ease.}
#'   \item{C1}{I am always prepared.}
#'   \item{C2}{I leave my belongings around.}
#'   \item{C3}{I pay attention to details.}
#'   \item{C4}{I make a mess of things.}
#'   \item{C5}{I get chores done right away.}
#'   \item{C6}{I often forget to put things back in their proper place.}
#'   \item{C7}{I like order.}
#'   \item{C8}{I shirk my duties.}
#'   \item{C9}{I follow a schedule.}
#'   \item{C10}{I am exacting in my work.}
#'   \item{O1}{I have a rich vocabulary.}
#'   \item{O2}{I have difficulty understanding abstract ideas.}
#'   \item{O3}{I have a vivid imagination.}
#'   \item{O4}{I am not interested in abstract ideas.}
#'   \item{O5}{I have excellent ideas.}
#'   \item{O6}{I do not have a good imagination.}
#'   \item{O7}{I am quick to understand things.}
#'   \item{O8}{I use difficult words.}
#'   \item{O9}{I spend time reflecting on things.}
#'   \item{O10}{I am full of ideas.}
#' }
#'
#' @details
#' Personality items were rated on a five-point Likert scale: #' 1=Disagree, 3=Neutral, 5=Agree. Missed=0.
#' 
#' \strong{race} Chosen from a drop down menu. 1=Mixed Race, 2=Arctic (Siberian, Eskimo), 3=Caucasian (European), 4=Caucasian (Indian), 5=Caucasian (Middle East), 6=Caucasian (North African, Other), 7=Indigenous Australian, 8=Native American, 9=North East Asian (Mongol, Tibetan, Korean Japanese, etc), 10=Pacific (Polynesian, Micronesian, etc), 11=South East Asian (Chinese, Thai, Malay, Filipino, etc), 12=West African, Bushmen, Ethiopian, 13=Other (0=missed)
#' \strong{age}	Entered as text (individuals reporting age < 13 were not recorded)
#' \strong{engnat}	Response to "is English your native language?". 1=Yes, 2=No (0=missed)
#' \strong{gender}	Chosen from a drop down menu. 1=Male, 2=Female, 3=Other (0=missed)
#' \strong{hand}	"What hand do you use to write with?". 1=Right, 2=Left, 3=Both (0=missed)
#' 
#' On this page users were also asked to confirm that their answers were accurate and could be used for research. Participants who did not were not recorded). Some values were calculated from technical information.
#' 
#' \strong{country}	The participant's technical location. ISO country code.
#' \strong{source}	How the participant came to the test. Based on HTTP Referrer. 1=from another page on the test website, 2=from google, 3=from facebook, 4=from any url with ".edu" in its domain name (e.g. xxx.edu, xxx.edu.au), 6=other source, or HTTP Referer not provided.
#' 
#' In psychological trait theory, the Big Five personality traits, also known as the five-factor model (FFM) and the OCEAN model, is a suggested taxonomy, or grouping, for personality traits, developed from the 1980s onwards. When factor analysis (a statistical technique) is applied to personality survey data, some words used to describe aspects of personality are often applied to the same person. For example, someone described as conscientious is more likely to be described as "always prepared" rather than "messy". This theory is based therefore on semantic associations between words and not on neuropsychological experiments. This theory uses descriptors of common language and suggests five broad dimensions commonly used to describe the human personality and psyche.
#' 
#' The theory identifies five factors:
#' \itemize{
#'   \item \strong{Openness to experience (O)} (inventive/curious vs. consistent/cautious)
#'   \item \strong{Conscientiousness (C)} (efficient/organized vs. extravagant/careless)
#'   \item \strong{Extraversion (E)} (outgoing/energetic vs. solitary/reserved)
#'   \item \strong{Agreeableness (A)} (friendly/compassionate vs. challenging/callous)
#'   \item \strong{Neuroticism (N)} (sensitive/nervous vs. resilient/confident)
#' }
#' The five factors are represented using the acronyms OCEAN or CANOE. Beneath each proposed global factor, there are a number of correlated and more specific primary factors. For example, extroversion is typically associated with qualities such as gregariousness, assertiveness, excitement-seeking, warmth, activity, and positive emotions.  
#' Family life and the way someone was raised will affect these traits. Twin studies and other research have shown that about half of the variation between individuals results from their genetics and half from their environments. Researchers have found conscientiousness, extroversion, openness to experience, and neuroticism to be relatively stable from childhood through adulthood.
#' 
#' Items are grouped by Big Five traits:
#' \itemize{
#'   \item \strong{Extraversion (E)}: E1 to E10
#'   \item \strong{Neuroticism (N)}: N1 to N10
#'   \item \strong{Agreeableness (A)}: A1 to A10
#'   \item \strong{Conscientiousness (C)}: C1 to C10
#'   \item \strong{Openness (O)}: O1 to O10
#' }
#'
#' Negatively keyed items are: E2, E4, E6, E8, E10, N2, N4, A1, A3, A5, A7, C2, C4, C6, C8, O2, O4, O6.
#' These should be reverse-coded prior to scoring.
#'
#' @source
#' Collected via an online personality test with informed consent (~2012).
#' Downloaded from Kaggle.com by the user Lucas Greenwell. see \url{https://www.kaggle.com/datasets/lucasgreenwell/ocean-five-factor-personality-test-responses}
#' 
#' @examples
#' data(df_ocean)
#' head(df_ocean)
#' 
#' # Compute Big Five average scores (after reverse scoring)
#' # library(dplyr)
#' # df_ocean <- df_ocean %>% mutate(E=rowMeans(select(., E1:E10), na.rm=TRUE))
#' @examples
#' data(df_ocean)
#' head(df_ocean)
"df_ocean"

#' Young People Survey Responses
#'
#' Survey responses from 1010 young people (15-30 years old) on music preferences,
#' movie preferences, hobbies, phobias, health habits, personality traits,
#' spending habits, and demographics.
#'
#' @format A data frame with 1010 rows and 151 variables. All preference and
#'   personality items are rated on a 1-5 Likert scale (1=strongly disagree /
#'   not interested, 5=strongly agree / very interested) unless otherwise noted.
#' \itemize{
#'   \item \strong{Participant Number}: Unique participant identifier
#'   \item \strong{Music}: Interest in music generally
#'   \item \strong{Slow songs or fast songs}: Preference for slow vs fast songs
#'   \item \strong{Dance}: Interest in dance music
#'   \item \strong{Folk}: Interest in folk music
#'   \item \strong{Country}: Interest in country music
#'   \item \strong{Classical music}: Interest in classical music
#'   \item \strong{Musical}: Interest in musicals
#'   \item \strong{Pop}: Interest in pop music
#'   \item \strong{Rock}: Interest in rock music
#'   \item \strong{Metal or Hardrock}: Interest in metal/hardrock
#'   \item \strong{Punk}: Interest in punk music
#'   \item \strong{Hiphop, Rap}: Interest in hiphop/rap
#'   \item \strong{Reggae, Ska}: Interest in reggae/ska
#'   \item \strong{Swing, Jazz}: Interest in swing/jazz
#'   \item \strong{Rock n roll}: Interest in rock n roll
#'   \item \strong{Alternative}: Interest in alternative music
#'   \item \strong{Latino}: Interest in Latino music
#'   \item \strong{Techno, Trance}: Interest in techno/trance
#'   \item \strong{Opera}: Interest in opera
#'   \item \strong{Movies}: Interest in movies generally
#'   \item \strong{Horror}: Interest in horror films
#'   \item \strong{Thriller}: Interest in thrillers
#'   \item \strong{Comedy}: Interest in comedy films
#'   \item \strong{Romantic}: Interest in romantic films
#'   \item \strong{Sci-fi}: Interest in sci-fi films
#'   \item \strong{War}: Interest in war films
#'   \item \strong{Fantasy/Fairy tales}: Interest in fantasy films
#'   \item \strong{Animated}: Interest in animated films
#'   \item \strong{Documentary}: Interest in documentaries
#'   \item \strong{Western}: Interest in westerns
#'   \item \strong{Action}: Interest in action films
#'   \item \strong{History}: Interest in history
#'   \item \strong{Psychology}: Interest in psychology
#'   \item \strong{Politics}: Interest in politics
#'   \item \strong{Mathematics}: Interest in mathematics
#'   \item \strong{Physics}: Interest in physics
#'   \item \strong{Internet}: Interest in internet
#'   \item \strong{PC}: Interest in computers
#'   \item \strong{Economy Management}: Interest in economy/management
#'   \item \strong{Biology}: Interest in biology
#'   \item \strong{Chemistry}: Interest in chemistry
#'   \item \strong{Reading}: Interest in reading
#'   \item \strong{Geography}: Interest in geography
#'   \item \strong{Foreign languages}: Interest in foreign languages
#'   \item \strong{Medicine}: Interest in medicine
#'   \item \strong{Law}: Interest in law
#'   \item \strong{Cars}: Interest in cars
#'   \item \strong{Art exhibitions}: Interest in art exhibitions
#'   \item \strong{Religion}: Interest in religion
#'   \item \strong{Countryside, outdoors}: Interest in countryside/outdoors
#'   \item \strong{Dancing}: Interest in dancing
#'   \item \strong{Musical instruments}: Interest in playing musical instruments
#'   \item \strong{Writing}: Interest in writing
#'   \item \strong{Passive sport}: Interest in watching sports
#'   \item \strong{Active sport}: Interest in playing sports
#'   \item \strong{Gardening}: Interest in gardening
#'   \item \strong{Celebrities}: Interest in celebrities
#'   \item \strong{Shopping}: Interest in shopping
#'   \item \strong{Science and technology}: Interest in science and technology
#'   \item \strong{Theatre}: Interest in theatre
#'   \item \strong{Fun with friends}: Enjoyment of socialising with friends
#'   \item \strong{Adrenaline sports}: Interest in adrenaline sports
#'   \item \strong{Pets}: Interest in pets
#'   \item \strong{Flying}: Fear of flying
#'   \item \strong{Storm}: Fear of storms
#'   \item \strong{Darkness}: Fear of darkness
#'   \item \strong{Heights}: Fear of heights
#'   \item \strong{Spiders}: Fear of spiders
#'   \item \strong{Snakes}: Fear of snakes
#'   \item \strong{Rats}: Fear of rats
#'   \item \strong{Ageing}: Fear of ageing
#'   \item \strong{Dangerous dogs}: Fear of dangerous dogs
#'   \item \strong{Fear of public speaking}: Fear of public speaking
